-- Run once against the TiDB database. Use a dedicated least-privilege application user.
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, discord_id VARCHAR(32) NOT NULL UNIQUE, display_name VARCHAR(100) NOT NULL, avatar VARCHAR(255), role_status ENUM('active','suspended','banned') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kind ENUM('game','emulator') NOT NULL, name VARCHAR(180) NOT NULL, name_key VARCHAR(180) NOT NULL, description TEXT, image_url VARCHAR(2048), image_attribution VARCHAR(500), wikipedia_url VARCHAR(2048), official_url VARCHAR(2048), trailer_url VARCHAR(2048), release_info VARCHAR(255), versions TEXT, owner_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY unique_entry (kind,name_key), KEY catalog (kind,name,id), FOREIGN KEY (owner_id) REFERENCES users(id));
CREATE TABLE reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, game_id BIGINT UNSIGNED NOT NULL, emulator_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, revision VARCHAR(120) NOT NULL, os VARCHAR(120) NOT NULL, cpu VARCHAR(180) NOT NULL, gpu VARCHAR(180) NOT NULL, result ENUM('Perfect','Playable','In-Game','Intro/Menu',"Won't Boot",'Not Tested') NOT NULL, game_version VARCHAR(120), fps VARCHAR(80), graphics TEXT, settings TEXT, notes TEXT, tested_at DATE NOT NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY game_reports (game_id,status,tested_at,id), KEY emulator_reports (emulator_id,status,tested_at,id), KEY user_reports (user_id,created_at), KEY moderation_queue (status,created_at,id), FOREIGN KEY (game_id) REFERENCES entries(id), FOREIGN KEY (emulator_id) REFERENCES entries(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE flags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, report_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, reason VARCHAR(500) NOT NULL, status ENUM('open','resolved') NOT NULL DEFAULT 'open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY one_flag (report_id,user_id), KEY flag_queue (status,created_at), FOREIGN KEY (report_id) REFERENCES reports(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE moderation_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, admin_id BIGINT UNSIGNED NOT NULL, action VARCHAR(80) NOT NULL, target_type VARCHAR(30) NOT NULL, target_id BIGINT UNSIGNED NOT NULL, details VARCHAR(1000), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, KEY history (created_at,id), FOREIGN KEY (admin_id) REFERENCES users(id));
